export const isVideo=file=>/^video\//.test(file.type)||/\.(mp4|mov|m4v|webm)$/i.test(file.name);
export function recordingType(Recorder=globalThis.MediaRecorder){if(!Recorder)return '';return ['video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(t=>Recorder.isTypeSupported(t))||'';}
